#!/bin/sh
# Generated by sdk-kit 0.1.0 — do not edit; change sdk-kit and run "sdk-kit sync"
#
# compose-run.sh — run one language's Docker integration suite (SPEC §8) and always clean up.
#
# usage: compose-run.sh [options] <typescript|rust|go|python|java> [-- ARGS...]
#   -f FILE     compose file; repeatable (default: docker/compose.yml next to this folder)
#   -p PREFIX   project name prefix (default: name of the repository folder)
#   -P NAME     exact project name (default: <prefix>-<lang>-<random>)
#   -l LOCK     serialise Docker runs with flock(1): "none" (default), "auto" (first free of
#               sdk-docker-1..N, else wait for a random one), a number N, or a lock file path.
#               Default comes from $SDK_DOCKER_LOCK. Lock files live in $SDK_DOCKER_LOCK_DIR
#               (default ${XDG_CACHE_HOME:-~/.cache}/grow-sdk/locks), N = $SDK_DOCKER_LOCKS (4).
#   -t SECONDS  stop the test run after SECONDS (needs timeout(1)); 0 = no limit (default)
#   -n          do not force a rebuild (only useful with GROW_TEST_IMAGE_TAG set to a kept image)
#   ARGS        passed to the test container instead of its default command
#
# What it does:  docker compose -p <project> --profile <lang> run --rm --build test-<lang>
# then, whatever happened:  docker compose -p <project> down -v --remove-orphans
# The test image is tagged with the project name ($GROW_TEST_IMAGE_TAG) and removed afterwards, so
# parallel runs never share a tag (the build cache keeps rebuilds fast).
# On failure the logs of every other service (service, bootstrap, ...) are printed.
# Exit status: the test container's exit status (2 for usage errors, 124 on timeout).
set -eu

LANGS="typescript rust go python java"
here=$(cd "$(dirname "$0")" && pwd)
compose_files=""
prefix=""
project=""
lock=${SDK_DOCKER_LOCK:-none}
lock_dir=${SDK_DOCKER_LOCK_DIR:-${XDG_CACHE_HOME:-$HOME/.cache}/grow-sdk/locks}
lock_count=${SDK_DOCKER_LOCKS:-4}
run_timeout=0
build=1

say() {
	printf 'compose-run: %s\n' "$*" >&2
}

usage() {
	sed -n '4,21p' "$0" | sed 's/^# \{0,1\}//' >&2
	exit 2
}

is_uint() {
	case $1 in '' | *[!0-9]*) return 1 ;; esac
	return 0
}

while getopts "f:p:P:l:t:nh" opt; do
	case $opt in
	f) compose_files="$compose_files
$OPTARG" ;;
	p) prefix=$OPTARG ;;
	P) project=$OPTARG ;;
	l) lock=$OPTARG ;;
	t) run_timeout=$OPTARG ;;
	n) build=0 ;;
	*) usage ;;
	esac
done
shift $((OPTIND - 1))
[ $# -ge 1 ] || usage
lang=$1
shift
case " $LANGS " in *" $lang "*) ;; *)
	say "unknown language '$lang' (expected one of: $LANGS)"
	exit 2
	;;
esac
if [ $# -gt 0 ]; then
	[ "$1" = "--" ] || usage
	shift
fi
is_uint "$run_timeout" || usage
is_uint "$lock_count" && [ "$lock_count" -ge 1 ] || lock_count=4

[ -n "$compose_files" ] || compose_files="
$here/../compose.yml"

random_id() {
	od -An -N4 -tx1 /dev/urandom | tr -d ' \n'
}

sanitize() {
	printf '%s' "$1" | tr '[:upper:]' '[:lower:]' | tr -c 'a-z0-9_-' '-' | sed 's/^[^a-z0-9]*//'
}

if [ -z "$project" ]; then
	if [ -z "$prefix" ]; then
		first=$(printf '%s\n' "$compose_files" | sed -n '2p')
		prefix=$(basename "$(cd "$(dirname "$first")/.." && pwd)")
	fi
	project="$(sanitize "$prefix")-$lang-$(random_id)"
fi
project=$(sanitize "$project")
[ -n "$project" ] || usage

# --- the compose command -------------------------------------------------------
# compose ARGS...  runs "docker compose -f FILE... ARGS..." (prefixed by $compose_wrapper)
compose_wrapper=""
compose() {
	_rev=$(printf '%s\n' "$compose_files" | sed '/^$/d' | sed -n '1!G;h;$p')
	while IFS= read -r _f; do
		set -- -f "$_f" "$@"
	done <<EOF
$_rev
EOF
	# shellcheck disable=SC2086 # the wrapper is a word list on purpose
	$compose_wrapper docker compose "$@"
}

# --- optional lock -----------------------------------------------------------------
acquire_lock() {
	command -v flock >/dev/null 2>&1 || {
		say "flock(1) is not installed; cannot honour -l $lock"
		exit 2
	}
	case $lock in
	auto)
		mkdir -p "$lock_dir"
		i=1
		while [ "$i" -le "$lock_count" ]; do
			lock_file="$lock_dir/sdk-docker-$i.lock"
			exec 9>>"$lock_file"
			if flock -n 9; then
				say "lock $lock_file"
				return 0
			fi
			exec 9>&-
			i=$((i + 1))
		done
		n=$(($(od -An -N1 -tu1 /dev/urandom | tr -d ' ') % lock_count + 1))
		lock_file="$lock_dir/sdk-docker-$n.lock"
		;;
	*/*) lock_file=$lock ;;
	*)
		is_uint "$lock" || {
			say "invalid lock '$lock'"
			exit 2
		}
		mkdir -p "$lock_dir"
		lock_file="$lock_dir/sdk-docker-$lock.lock"
		;;
	esac
	exec 9>>"$lock_file"
	say "waiting for lock $lock_file"
	flock 9
	say "lock $lock_file"
}

case $lock in none | "" | 0) ;; *) acquire_lock ;; esac

# --- run ---------------------------------------------------------------------------------
cleaned=0
remove_image=0
GROW_TEST_IMAGE_TAG=${GROW_TEST_IMAGE_TAG:-}
# shellcheck disable=SC2329 # invoked by the EXIT trap
cleanup() {
	[ "$cleaned" -eq 0 ] || return 0
	cleaned=1
	compose_wrapper=""
	say "cleaning up project $project"
	compose -p "$project" --profile "$lang" down -v --remove-orphans --timeout 10 >/dev/null 2>&1 ||
		say "warning: 'docker compose down' failed for project $project"
	if [ "$remove_image" -eq 1 ]; then
		for image in $(compose -p "$project" --profile "$lang" config --images 2>/dev/null | grep -- "-test-$lang:$GROW_TEST_IMAGE_TAG\$" || true); do
			docker image rm "$image" >/dev/null 2>&1 || true
		done
	fi
}
child=""
# shellcheck disable=SC2329 # invoked by the INT/TERM traps
on_signal() {
	[ -z "$child" ] || kill -TERM "$child" 2>/dev/null || true
	exit "$1"
}
trap 'cleanup' EXIT
trap 'on_signal 130' INT
trap 'on_signal 143' TERM

GROW_TEST_RUN_ID=${GROW_TEST_RUN_ID:-$(random_id)}
export GROW_TEST_RUN_ID
remove_image=0
if [ -z "${GROW_TEST_IMAGE_TAG:-}" ]; then
	GROW_TEST_IMAGE_TAG=$project
	remove_image=1
fi
export GROW_TEST_IMAGE_TAG
say "project $project, profile $lang, run id $GROW_TEST_RUN_ID"

if [ "$build" -eq 1 ]; then
	set -- -p "$project" --profile "$lang" run --rm --build "test-$lang" "$@"
else
	set -- -p "$project" --profile "$lang" run --rm "test-$lang" "$@"
fi
_rev=$(printf '%s\n' "$compose_files" | sed '/^$/d' | sed -n '1!G;h;$p')
while IFS= read -r _f; do
	set -- -f "$_f" "$@"
done <<EOF
$_rev
EOF
if [ "$run_timeout" -gt 0 ]; then
	command -v timeout >/dev/null 2>&1 || {
		say "timeout(1) is not installed; cannot honour -t"
		exit 2
	}
	compose_wrapper="timeout -k 15 $run_timeout"
fi

# Run in the background and wait, so INT/TERM reach the trap at once (and stop the run).
rc=0
# shellcheck disable=SC2086 # the wrapper is a word list on purpose
$compose_wrapper docker compose "$@" &
child=$!
wait "$child" || rc=$?
child=""
compose_wrapper=""

if [ "$rc" -ne 0 ]; then
	[ "$rc" -ne 124 ] || say "test run timed out after ${run_timeout}s"
	say "test-$lang failed with exit status $rc; service state and logs follow"
	compose -p "$project" --profile "$lang" ps -a >&2 || true
	compose -p "$project" --profile "$lang" logs --no-color --timestamps >&2 || true
else
	say "test-$lang passed"
fi
exit "$rc"
